import React, {type FC} from 'react';

import {
    ChevronDownWide,
    ChevronUpWide,
    ChevronsDownWide,
    ChevronsUpWide,
    CircleExclamation,
    Equal,
} from '@gravity-ui/icons';
import {type IconData, getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import type {IconRefugeProps} from '../IconRefuge';
import {IconRefuge} from '../IconRefuge';

import {cnPriorityIcon} from './PriorityIcon.classname';
import {defaultMessages} from './i18n';
import type {Priority} from './types';

import './PriorityIcon.scss';

export type PriorityIconProps = Partial<Pick<IconRefugeProps, 'containerClassName' | 'title'>> & {
    className?: string;
    size?: number;
    priority?: Priority;
    showBackground?: boolean;
    backgroundSize?: number;
    metaEntity?: boolean;
};

const getIconData = (priority: Priority, metaEntity?: boolean): IconData => {
    switch (priority) {
        case 'blocker':
            return CircleExclamation;
        case 'critical':
            return metaEntity ? CircleExclamation : ChevronsUpWide;
        case 'minor':
            return ChevronDownWide;
        case 'trivial':
        case 'minimal':
            return ChevronsDownWide;
        case 'important':
            return ChevronUpWide;
        default:
            return Equal;
    }
};

export const PriorityIcon: FC<PriorityIconProps> = ({
    className,
    containerClassName,
    priority = 'normal',
    size = 16,
    title,
    showBackground,
    backgroundSize,
    metaEntity,
}) => {
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);
    const ariaLabel = title ? t('priority-label', {priority: title}) : undefined;

    const iconNode = (
        <IconRefuge
            containerClassName={containerClassName}
            className={cnPriorityIcon({priority, metaEntity}, className)}
            data={getIconData(priority, metaEntity)}
            refugeSize={size}
            title={title}
            aria-label={ariaLabel}
            aria-hidden={!title || undefined}
        />
    );

    if (!showBackground) {
        return iconNode;
    }

    return (
        <div
            className={cnPriorityIcon('background', {priority, metaEntity})}
            style={
                backgroundSize
                    ? {
                          width: backgroundSize,
                          height: backgroundSize,
                          minWidth: backgroundSize,
                      }
                    : undefined
            }
        >
            {iconNode}
        </div>
    );
};

PriorityIcon.displayName = 'PriorityIcon';
